  Lemma merge_sb' : forall j (q : nat) (v : word),
      (0 <= j)%Z -> (j + 8 <= n)%Z -> (1 <= q <= 3)%nat ->
      v = v_or (v_srliw (LWv (sb_ j 4)) (8 * Z.of_nat q)) (v_slli (LWv (sb_ (j + 4) 4)) (32 - 8 * Z.of_nat q)) ->
      word_to_le_bytes 4 v = sb_ (j + Z.of_nat q) 4.
Proof.
